import { ERROR_MESSAGE } from '../Constant';
import Request from '../Request';
import Response from '../Response';
/**
 * Fetch
 * @class Fetch
 * @classdesc 客户端发送消息
 */
class Fetch {
    // 发送方的window
    source;
    // 发送方的origin
    origin;
    constructor(source, origin) {
        this.source = source;
        this.origin = origin;
    }
    /**
     * send
     * @description 发送一个请求
     * @param targetWindow 目标window
     * @param targetOrigin 目标origin
     * @param pathname 路径
     * @param options 配置
     * @return Promise<Response>
     */
    send(targetWindow, targetOrigin, pathname, options) {
        return new Promise((resolve, reject) => {
            const request = new Request({
                pathname,
                headers: {
                    ...(options?.headers ?? {}),
                    origin: this.origin,
                    referer: this.source instanceof Window ? this.source.location.href : '',
                },
                statusCode: 0,
                stateMessage: ERROR_MESSAGE,
                body: options?.data,
                type: 'request',
            });
            const onMessage = (evt) => {
                try {
                    const response = new Response(JSON.parse(evt.data));
                    // response.setRequestId(evt.data.requestId);
                    if (evt.origin !== targetOrigin ||
                        evt.source !== targetWindow ||
                        request.getRequestId() !== response.getRequestId()) {
                        return;
                    }
                    if (response?.type === 'request') {
                        return;
                    }
                    this.source.removeEventListener('message', onMessage);
                    if (response.getStatusCode() === 500) {
                        reject(response);
                        return;
                    }
                    resolve(response);
                }
                catch (e) {
                    console.warn(e);
                }
            };
            this.source.addEventListener('message', onMessage);
            try {
                // @ts-ignore
                targetWindow.postMessage(JSON.stringify(request), targetOrigin);
            }
            catch (e) {
                console.error(e);
            }
        });
    }
    /**
     * get
     * @param params
     */
    get(...params) {
        // @ts-ignore
        return this.send(...params);
    }
    /**
     * put
     * @param params
     */
    put(...params) {
        // @ts-ignore
        return this.send(...params);
    }
    /**
     * delete
     * @param params
     */
    delete(...params) {
        // @ts-ignore
        return this.send(...params);
    }
}
export default Fetch;
